import {chapters,textbook,read,e} from '../shared/course.js';
import {progressGuard,revisionKey} from '../shared/progress.js';
import {modules,facts} from './content.js';
import {figures} from './figures.js';
import {specimens} from './specimens.js';
import {lab,labOptions} from './labs.js';
import {bank,makeSession,correct,result,validSession,sectionCounts} from './engine.js';
const key='soma-tissue-studio-v1',draftKey='soma-tissue-draft-v1',root=document.querySelector('#app');
const saved=read(key),draft=read(draftKey);
let state={module:'types',tab:'learn',lesson:0,labels:true,paused:true,detail:true,view:'lab',mode:'families',step:0,layers:1,shape:'cuboidal',secretion:'merocrine',stretch:false,figure:0,specimenIndex:0,specimenReveal:false,term:null,termPage:0,reviewAll:false,reviewPage:0,stats:saved.stats||{},session:validSession(draft.session)?draft.session:null,error:false};
const guard=progressGuard(localStorage,()=>location.replace('../#/review'));
if(draft.ui&&modules.some(m=>m.id===draft.ui.module)){const u=draft.ui;state.module=u.module;state.mode=labOptions[u.module].some(([id])=>id===u.mode)?u.mode:labOptions[u.module][0][0];state.view=['lab','figures','specimens'].includes(u.view)&&!(u.view==='specimens'&&!specimens.some(s=>s.module===u.module))?u.view:'lab';for(const k of ['labels','paused','stretch'])if(typeof u[k]==='boolean')state[k]=u[k];for(const k of ['step','figure','specimenIndex'])if(Number.isInteger(u[k])&&u[k]>=0&&u[k]<30)state[k]=u[k];if([1,3].includes(u.layers))state.layers=u.layers;if(['squamous','cuboidal','columnar'].includes(u.shape))state.shape=u.shape;if(['merocrine','apocrine','holocrine'].includes(u.secretion))state.secretion=u.secretion;}
const mod=()=>modules.find(m=>m.id===state.module);
const lesson=()=>mod().lessons[state.lesson];
const route=(tab=state.tab,lessonId=lesson().id)=>`#module/${state.module}/${tab}/${lessonId}`;
const source=m=>textbook([m.section,m.title]);
function microscope(){const list=specimens.filter(s=>s.module===state.module),s=list[state.specimenIndex%list.length];return `<div class="split"><section class="panel visual-panel"><div class="visual-title"><b>${state.specimenReveal?e(s.name):'Identify the tissue'}</b><span>REAL TEXTBOOK MICROGRAPH</span></div><div class="figure-image specimen-image"><img src="${s.src}" alt="Textbook micrograph for tissue identification"></div><div class="lab-caption">${state.specimenReveal?e(s.evidence):'Describe the cell shape, nuclei, fiber pattern and space between cells before revealing the answer.'}</div></section><aside class="panel"><p class="eyebrow">LOOK → NAME → JUSTIFY</p><h2>What is your evidence?</h2><p>Say the tissue name and two features you can actually see. Then check the explanation.</p><button class="primary" id="specimen-reveal">${state.specimenReveal?'Hide identification':'Reveal identification & evidence'}</button>${state.specimenReveal?`<div class="cue"><b>${e(s.name)}</b><br>${e(s.contrast)}</div><p class="credit">${e(s.credit)}</p>`:'<p class="credit">A crop of a Chapter 4 textbook example. Full source and identification are shown on reveal. Crops are not independent unseen specimens.</p>'}<div class="pager"><button id="specimen-prev">← Previous</button><span>${state.specimenIndex%list.length+1} / ${list.length}</span><button id="specimen-next">Next →</button></div></aside></div>`;}
function save(){if(!guard())return;try{const prior=read(key).stats||{};for(const [id,s] of Object.entries(prior))if((s.updatedAt||0)>(state.stats[id]?.updatedAt||0))state.stats[id]=s;localStorage.setItem(key,JSON.stringify({stats:state.stats}));localStorage.setItem(draftKey,JSON.stringify({session:state.session,ui:Object.fromEntries(['module','mode','view','labels','paused','step','layers','shape','secretion','stretch','figure','specimenIndex'].map(k=>[k,state[k]]))}));localStorage.setItem('soma-resume-v1',JSON.stringify({url:'chapter4/'+location.hash,label:'Chapter 4 · '+mod().short}));}catch{state.error=true;}}
function pageRoute(){const bits=location.hash.slice(1).split('/');if(bits[0]==='module'){const m=modules.find(m=>m.id===bits[1]);if(m){if(state.module!==m.id){state.module=m.id;state.mode=labOptions[m.id][0][0];state.figure=0;state.specimenIndex=0;state.specimenReveal=false;state.view='lab';state.step=0;state.term=null;}state.tab=['learn','explore','practice','review'].includes(bits[2])?bits[2]:'learn';state.termPage=0;state.lesson=Math.max(0,m.lessons.findIndex(l=>l.id===bits[3]));}}else state.tab=bits[0]==='exam'?'exam':bits[0]==='review'?'review':bits[0]==='session'?'session':'learn';render();}
function header(){return `<header class="top"><a class="brand" href="../">soma<em>.</em></a><select id="chapter" aria-label="Choose chapter">${chapters.map(c=>`<option value="${c.id}" ${c.id===4?'selected':''}>Chapter ${c.id} · ${e(c.short)}</option>`).join('')}</select><nav aria-label="Course"><a href="../">Chapters</a><a href="../#/review">Review & progress</a><button id="effects">Effects ${read('soma-motion','on')}</button></nav></header>`;}
function sidebar(){return `<aside class="sidebar"><p class="eyebrow">TISSUE STUDIO / 04</p>${modules.map(m=>`<a class="${state.module===m.id?'active':''}" href="#module/${m.id}/learn"><b>${m.section}</b><span>${e(m.short)}</span></a>`).join('')}<div class="bottom"><a href="#exam">Chapter 4 exam →</a><a href="../#/chapter/4">Chapter overview ↗</a><a href="../#/help">Help & progress backup ↗</a><small>Original figures from OpenStax A&P 2e.<br>Educational adaptations: CC BY-NC-SA 4.0.</small></div></aside>`;}
function pager(index,total,kind){return `<div class="pager"><button data-page="${kind}" data-delta="-1" ${index===0?'disabled':''}>← Previous</button><span>${index+1} / ${total}</span><button data-page="${kind}" data-delta="1" ${index===total-1?'disabled':''}>Next →</button></div>`;}
function learn(){const l=lesson();return `<div class="split"><article class="panel"><label class="eyebrow" for="lesson-picker">LESSON ${state.lesson+1} / ${mod().lessons.length}</label><select id="lesson-picker">${mod().lessons.map((item,i)=>`<option value="${i}" ${i===state.lesson?'selected':''}>${i+1}. ${e(item.title)}</option>`).join('')}</select><h2>${e(l.title)}</h2><p class="body-text">${e(l.body)}</p><div class="cue"><b>Memory cue</b><br>${e(l.cue)}</div><p class="trap"><b>Watch the distinction:</b> ${e(l.trap)}</p><div class="pager"><button data-lesson="-1" ${state.lesson===0?'disabled':''}>← Previous</button><span>${state.lesson+1} / ${mod().lessons.length}</span>${state.lesson<mod().lessons.length-1?'<button data-lesson="1">Next lesson →</button>':`<a class="action primary" href="${route('explore')}">Explore this section →</a>`}</div></article><aside class="panel"><p class="eyebrow">ACTIVE RECALL</p><h2>Say it before you reveal it.</h2><p class="credit">Choose a term to check your explanation. These reveals do not count as scored practice.</p><div class="term-list">${l.facts.slice(state.termPage*4,state.termPage*4+4).map(f=>`<button class="term ${state.term===f.id?'active':''}" data-term="${f.id}" aria-expanded="${state.term===f.id}">${e(f.term)}${state.term===f.id?`<small>${e(f.definition)}</small>`:''}</button>`).join('')}</div>${l.facts.length>4?`<div class="toolbar" style="margin-top:12px"><button data-term-page="-1" ${state.termPage===0?'disabled':''}>← Terms</button><span class="credit">${state.termPage+1} / ${Math.ceil(l.facts.length/4)}</span><button data-term-page="1" ${state.termPage===Math.ceil(l.facts.length/4)-1?'disabled':''}>More terms →</button></div>`:''}<div class="pager"><a href="${route('practice')}">Practice ${mod().section} →</a><a href="${source(mod())}" target="_blank" rel="noopener">Read full section ↗</a></div></aside></div>`;}
function explore(){
 const nav=`<div class="subtabs"><button data-view="lab" class="${state.view==='lab'?'active':''}">Guided textbook diagrams</button><button data-view="figures" class="${state.view==='figures'?'active':''}">All textbook figures</button>${specimens.some(x=>x.module===state.module)?`<button data-view="specimens" class="${state.view==='specimens'?'active':''}">Microscope challenge</button>`:''}</div>`;
 if(state.view==='specimens')return nav+microscope();
 const fs=figures.filter(f=>f.module===state.module),d=lab(state.module,state),f=state.view==='lab'?d.figure:fs[state.figure%fs.length];
 return nav+`<div class="split"><section class="panel visual-panel ${state.paused?'paused':''}"><div class="visual-title"><b>${state.view==='lab'?e(d.title):e(f.title)}</b><span>OPENSTAX · FIGURE ${f.id}</span></div>${state.view==='lab'?`<div class="diagram textbook-canvas">${d.svg}</div><div class="lab-caption">${e(d.caption)}</div>`:`<div class="figure-image"><img src="${f.src}" alt="Original OpenStax Figure ${f.id}: ${e(f.title)}" loading="eager"></div><div class="lab-caption">Original labels and leader lines retained. Open the full image for maximum resolution.</div>`}</section><aside class="panel explore-side"><p class="eyebrow">${state.view==='lab'?'LOOK CLOSELY. EXPLAIN WHAT YOU SEE.':'THE ORIGINAL TEXTBOOK ARTWORK'}</p>${state.view==='lab'?`<label for="diagram-topic">Explore a concept</label><select id="diagram-topic">${labOptions[state.module].map(([id,name])=>`<option value="${id}" ${state.mode===id?'selected':''}>${name}</option>`).join('')}</select><div class="tour-controls">${d.controls}</div><div class="toolbar"><label><input id="detail" type="checkbox" ${state.detail?'checked':''}> Enlarge selected panel</label><label><input id="labels" type="checkbox" ${state.labels?'checked':''}> Highlight focus</label></div>${d.steps>1?`<div class="tour-player"><button data-step="-1" aria-label="Previous guided step">←</button><span>${d.step+1} / ${d.steps}</span><button id="pause">${state.paused?'Play guided sequence':'Pause sequence'}</button><button data-step="1" aria-label="Next guided step">→</button></div>`:state.mode==='signal'?'<button id="pause">Play motion</button>':''}<div class="cue"><b>Check your understanding</b><p>${e(d.question)}</p></div><p class="credit">Printed labels stay visible. Animated guides show where to look and the order of events; the original tissue image is never stretched or distorted.</p>`:`<label for="figure">Choose a figure</label><select id="figure">${fs.map((x,i)=>`<option value="${i}" ${i===state.figure?'selected':''}>${x.id} · ${e(x.title)}</option>`).join('')}</select><p>${e(f.title)}</p><p class="credit">PDF page ${f.page} · printed page ${f.printedPage}.</p>`}<details class="figure-credit"><summary>Source & full-resolution image</summary><p class="credit">${e(f.credit)}</p><a href="${f.src}" target="_blank" rel="noopener">Open original figure ${f.id} ↗</a></details><div class="pager"><a href="${route('practice')}">Practice this section →</a></div></aside></div>`;
}
function setup(exam=false){const count=exam?40:Math.min(10,sectionCounts[state.module]);return `<div class="split"><section class="panel"><p class="eyebrow">${exam?'CHAPTER 4 ASSESSMENT':'RETRIEVE · EXPLAIN · IMPROVE'}</p><h2>${exam?'Bring the tissue story together.':'Turn recognition into recall.'}</h2><p>${exam?'40 questions across all six sections, with feedback after submission. Distribution: 6 tissue types, 10 epithelium, 10 connective, 5 muscle, 4 nervous and 5 injury/aging.':`${count} questions from ${mod().section}, with immediate explanations and links to the matching lesson.`}</p><div class="cue">${exam?'Recall, reasoning, textbook-detail identification and reviewed micrographs. These are familiar textbook examples, not an unseen specimen exam.':'Choose an answer before checking. If you use a hint, the attempt is recorded as assisted even if the answer is correct.'}</div><div class="pager"><button class="primary" id="start" data-exam="${exam}">Start ${exam?'chapter exam':'10-question practice'} →</button>${!exam?'<button id="retry">Practice missed or assisted</button>':''}</div></section><aside class="panel"><span class="welcome-mark" aria-hidden="true">◎</span><h2>${bank.length} reviewed questions.</h2><p>Connect tissue names to structure, function and evidence. No AI is needed for these activities.</p>${state.session?`<div class="cue">${state.session.submitted?'Your last results are saved.':'An unfinished session is saved on this browser.'}<br><a href="#session">${state.session.submitted?'View results':'Resume session'} →</a></div>`:''}<p class="credit">Progress is saved on this browser. Use Review & progress in the course header to back up or reset it.</p></aside></div>`;}
function record(id){const s=state.session;if(s.recorded[id])return;const q=bank.find(q=>q.id===id),prior=state.stats[id]||{},good=correct(q,s.answers[id]);state.stats[id]={attempts:(prior.attempts||0)+1,correct:(prior.correct||0)+Number(good),lastCorrect:good,response:s.answers[id]||'Unanswered',assisted:!!s.assisted[id],updatedAt:Date.now()};s.recorded[id]=true;}
function session(){const s=state.session;if(!s)return setup();if(s.submitted)return results();const q=bank.find(q=>q.id===s.ids[s.index]),specimen=specimens.find(x=>x.id===q.specimen),m=modules.find(m=>m.id===q.module),checked=!!s.recorded[q.id],value=s.answers[q.id];return `<article class="panel question"><div class="toolbar"><span class="eyebrow">${s.exam?'EXAM':'PRACTICE'} · ${s.index+1} / ${s.ids.length}</span><span style="margin-left:auto" class="eyebrow">${s.exam?'Feedback after submission':m.section+' · '+q.type}</span></div><h2 class="prompt">${e(q.prompt)}</h2>${q.visual?`<div class="diagram quiz-visual paused">${lab(q.visual.module,{...q.visual,labels:false}).svg}</div>`:''}${specimen?`<div class="quiz-micrograph"><img src="${specimen.src}" alt="Unlabeled textbook tissue specimen"></div>`:''}<div class="options">${s.options[q.id].map(v=>`<button class="option" data-answer="${e(v)}" aria-pressed="${value===v}" ${checked?'disabled':''}>${e(v)}</button>`).join('')}</div>${checked?`<div class="feedback" role="status"><b>${correct(q,value)?'Correct':'Not quite'}${s.assisted[q.id]?' · assisted':''} — ${e(q.answer)}</b><br>${e(q.explanation)}${specimen?`<p class="credit">${e(specimen.credit)}</p>`:''}<br><a href="#module/${q.module}/learn/${q.lesson}">Revisit the exact lesson →</a></div>`:s.assisted[q.id]?`<div class="cue">Hint: connect this question to “${e(m.lessons.find(l=>l.id===q.lesson).title)}.” Review the relevant distinguishing feature before choosing. <a href="#module/${q.module}/learn/${q.lesson}">Read the lesson ↗</a></div>`:''}<div class="pager">${s.exam?`<button id="previous-question" ${s.index===0?'disabled':''}>← Previous</button>`:checked?'<span>Feedback saved</span>':'<button id="hint">Use a hint</button>'}${s.exam?`<span>${Object.keys(s.answers).length} / ${s.ids.length} answered</span><button class="primary" id="next-question">${s.index===s.ids.length-1?'Submit exam':'Next →'}</button>`:checked?`<button class="primary" id="next-question">${s.index===s.ids.length-1?'See results':'Next →'}</button>`:`<button class="primary" id="check" ${!value?'disabled':''}>Check answer</button>`}</div></article>`;}
function results(){const r=result(state.session);return `<article class="panel question"><p class="eyebrow">SESSION COMPLETE</p><h2>Keep the evidence. Revisit the gaps.</h2><div class="metric-row"><div class="metric"><strong>${r.independent}/${r.total}</strong><span>Correct without help</span></div><div class="metric"><strong>${r.assisted}</strong><span>Correct with help</span></div><div class="metric"><strong>${r.missed}</strong><span>Missed or assisted</span></div></div><p>Your latest answers are saved. Review explains each answer and links back to its lesson.</p><div class="toolbar"><a class="action primary" href="#review">Review chapter answers →</a><a class="action" href="${route('practice')}">Practice again</a><a class="action" href="#exam">Chapter exam</a></div></article>`;}
function review(){const all=location.hash==='#review',qs=bank.filter(q=>(all||q.module===state.module)&&state.stats[q.id]),due=qs.filter(q=>!state.stats[q.id].lastCorrect||state.stats[q.id].assisted),list=state.reviewAll?qs:due.length?due:qs,pages=Math.max(1,list.length);state.reviewPage=Math.min(state.reviewPage,pages-1);return `<article class="panel"><p class="eyebrow">${all?'CHAPTER 4':mod().section} · REVIEW</p><h2>${due.length?'Make the next attempt stronger.':'Your learning record.'}</h2><div class="toolbar"><span>${qs.length} attempted · ${due.length} missed or assisted</span><button id="retry">Practice missed or assisted</button><button id="review-filter">${state.reviewAll?'Show missed or assisted':'Show all attempted'}</button></div>${list.slice(state.reviewPage,state.reviewPage+1).map(q=>`<div class="review-row"><div><p>${e(q.prompt)}</p><p class="credit">Your latest response: ${e(state.stats[q.id].response||'Recorded in another course activity')}</p><b>${e(q.answer)}</b><p>${e(q.explanation)}</p>${q.specimen?`<p class="credit">${e(specimens.find(s=>s.id===q.specimen).credit)}</p>`:''}<small>${state.stats[q.id].assisted?'Assisted':state.stats[q.id].lastCorrect?'Latest answer correct':'Needs review'}</small></div><a href="#module/${q.module}/learn/${q.lesson}">Learn why →</a></div>`).join('')||'<p class="empty">No attempts yet. Start a section practice or the chapter exam.</p>'}${pager(state.reviewPage,pages,'review')}<p class="credit">Latest outcomes are evidence of recall, not a guarantee of mastery. <a href="../#/review">Back up or reset all course progress ↗</a></p></article>`;}
let tourTimer;
function render(){clearTimeout(tourTimer);const active=document.activeElement,focusKey=active?.id?'#'+CSS.escape(active.id):['data-term','data-mode','data-answer','data-step','data-view','data-page'].find(k=>active?.hasAttribute(k)),focusSelector=focusKey?.startsWith('#')?focusKey:focusKey?`[${focusKey}="${CSS.escape(active.getAttribute(focusKey))}"]`:null;save();document.documentElement.dataset.motion=read('soma-motion','on');const special=['exam','session'].includes(state.tab);root.innerHTML=header()+`<div class="shell">${sidebar()}<main class="workspace" id="main"><div class="heading"><div><p class="eyebrow">CHAPTER 04 / THE TISSUE LEVEL OF ORGANIZATION</p><h1>${state.tab==='exam'?'Chapter exam':state.tab==='session'?'Practice & assessment':state.tab==='review'&&location.hash==='#review'?'Chapter review':e(mod().short)}</h1><p class="subtitle">${e(mod().intro)}</p></div><a class="action" href="${source(mod())}" target="_blank" rel="noopener">Read ${mod().section} ↗</a></div>${!special?`<nav class="tabs" aria-label="Learning activities">${['learn','explore','practice','review'].map(t=>`<a href="${route(t)}" class="${state.tab===t?'active':''}" ${state.tab===t?'aria-current="page"':''}>${t[0].toUpperCase()+t.slice(1)}</a>`).join('')}<a href="../local-ai/?section=${mod().section}&tool=tutor">AI tutor ↗</a><a href="../local-ai/?section=${mod().section}&tool=quiz">AI practice ↗</a></nav>`:''}${state.error?'<div class="notice" role="status">Browser storage is unavailable. This session works, but progress may not survive closing this page.</div>':''}<div class="content">${state.tab==='explore'?explore():state.tab==='practice'?setup():state.tab==='exam'?setup(true):state.tab==='session'?session():state.tab==='review'?review():learn()}</div><footer class="footer"><span>OpenStax A&P 2e · CC BY-NC-SA 4.0 · Tissue Studio</span><a href="#exam">Chapter exam →</a></footer></main></div>`;bind();if(state.tab==='explore'&&state.view==='lab'&&!state.paused&&read('soma-motion','on')!=='off'&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){const d=lab(state.module,state);if(d.steps>1)tourTimer=setTimeout(()=>{if(state.step>=d.steps-1)state.paused=true;else state.step++;render();},7000);}if(focusSelector)root.querySelector(focusSelector)?.focus({preventScroll:true});}
function begin(exam=false,revisit=false){if(state.session&&!state.session.submitted&&!confirm('Replace your unfinished session? Its checked practice answers are already saved.'))return;const all=exam||location.hash==='#review';const next=makeSession({module:all?undefined:state.module,exam,revisit,stats:state.stats});if(!next.ids.length){alert('No missed or assisted questions in this selection yet.');return;}state.session=next;location.hash='session';if(state.tab==='session')render();}
function bind(){root.querySelector('#chapter').onchange=ev=>location.href=`../#/chapter/${ev.target.value}`;root.querySelector('#effects').onclick=()=>{try{localStorage.setItem('soma-motion',JSON.stringify(read('soma-motion','on')==='on'?'off':'on'));}catch{state.error=true;}render();};
 root.querySelector('#lesson-picker')?.addEventListener('change',ev=>{state.lesson=Number(ev.target.value);state.term=null;location.hash=route();});root.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{state.lesson+=Number(b.dataset.lesson);state.term=null;location.hash=route();});
 root.querySelectorAll('[data-term-page]').forEach(b=>b.onclick=()=>{state.termPage+=Number(b.dataset.termPage);state.term=null;render();});root.querySelectorAll('[data-term]').forEach(b=>b.onclick=()=>{state.term=state.term===b.dataset.term?null:b.dataset.term;render();});
 root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render();});root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;state.step=0;render();});
 root.querySelector('#diagram-topic')?.addEventListener('change',ev=>{state.mode=ev.target.value;state.step=0;state.paused=true;render();});root.querySelector('#detail')?.addEventListener('change',ev=>{state.detail=ev.target.checked;render();});root.querySelectorAll('[data-tour-step]').forEach(b=>b.onclick=()=>{state.step=Number(b.dataset.tourStep);state.paused=true;render();});
 root.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{state.step=(state.step+Number(b.dataset.step)+lab(state.module,state).steps)%lab(state.module,state).steps;state.paused=true;render();});root.querySelector('[data-stretch]')?.addEventListener('click',()=>{state.stretch=!state.stretch;render();});
 for(const id of ['layers','shape','secretion','figure'])root.querySelector('#'+id)?.addEventListener('change',ev=>{state[id]=['layers','figure'].includes(id)?Number(ev.target.value):ev.target.value;render();});
 root.querySelector('#specimen-reveal')?.addEventListener('click',()=>{state.specimenReveal=!state.specimenReveal;render();});for(const [id,delta] of [['specimen-prev',-1],['specimen-next',1]])root.querySelector('#'+id)?.addEventListener('click',()=>{const n=specimens.filter(x=>x.module===state.module).length;state.specimenIndex=(state.specimenIndex+delta+n)%n;state.specimenReveal=false;render();});root.querySelector('#labels')?.addEventListener('change',ev=>{state.labels=ev.target.checked;render();});root.querySelector('#pause')?.addEventListener('click',()=>{state.paused=!state.paused;render();});
 root.querySelector('#start')?.addEventListener('click',ev=>begin(ev.currentTarget.dataset.exam==='true'));root.querySelector('#review-filter')?.addEventListener('click',()=>{state.reviewAll=!state.reviewAll;state.reviewPage=0;render();});root.querySelector('#retry')?.addEventListener('click',()=>begin(false,true));
 root.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{state.session.answers[state.session.ids[state.session.index]]=b.dataset.answer;render();});
 root.querySelector('#hint')?.addEventListener('click',()=>{state.session.assisted[state.session.ids[state.session.index]]=true;render();});root.querySelector('#check')?.addEventListener('click',()=>{record(state.session.ids[state.session.index]);render();});
 root.querySelector('#previous-question')?.addEventListener('click',()=>{state.session.index--;render();});root.querySelector('#next-question')?.addEventListener('click',()=>{const s=state.session;if(s.index===s.ids.length-1){if(s.exam&&Object.keys(s.answers).length<s.ids.length&&!confirm('Submit with unanswered questions? Unanswered items count as missed.'))return;for(const id of s.ids)record(id);s.submitted=true;}else s.index++;render();});
 root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.reviewPage+=Number(b.dataset.delta);render();});
}
window.addEventListener('hashchange',pageRoute);window.addEventListener('storage',ev=>{if(ev.key===revisionKey)guard();if(ev.key==='soma-motion')render();});pageRoute();
